function EventTimeline(){return <section className="event-timeline"><p className="eyebrow">ACM BV × DSA TIMELINE</p><h2>LEARN THROUGH THE YEAR</h2><div>{[['2026','Foundations','Programming Basics'],['AUG','Arrays & Strings',''],['SEP','Linked Lists',''],['OCT','Stack & Queue',''],['NOV','Trees & Graphs',''],['DEC','Dynamic Programming',''],['FINAL','ACM DSA Challenge','']].map(([m,t,s],i)=><button key={m} onClick={()=>go('/learn/'+(roadmap[Math.min(i,roadmap.length-1)].id))}><b>{m}</b><span>{t}</span><small>{s}</small></button>)}</div></section>}
function CodeBlock(){const [lang,setLang]=useState('Java');const code={Java:'int[] arr = {10, 20, 30, 40};\n\nfor (int i = 0; i < arr.length; i++) {\n  System.out.println(arr[i]);\n}','C++':'vector<int> arr = {10, 20, 30, 40};\n\nfor (int value : arr) {\n  cout << value << endl;\n}',Python:'arr = [10, 20, 30, 40]\n\nfor value in arr:\n    print(value)'};return <section className="code-section"><div className="code-head"><div>{Object.keys(code).map(x=><button className={x===lang?'selected':''} onClick={()=>setLang(x)} key={x}>{x}</button>)}</div><button onClick={()=>navigator.clipboard?.writeText(code[lang])}>⧉ Copy</button></div><pre><code>{code[lang]}</code></pre></section>}
function ArrayLab(){const [arr,setArr]=useState([10,25,7,42,18]),[val,setVal]=useState(''),[selected,setSelected]=useState(null),[message,setMessage]=useState('Select an element to inspect it.');const mutate=(fn,msg)=>{setArr(fn);setMessage(msg);setSelected(null)};return <div className="lab"><div className="array-row">{arr.map((x,i)=><button className={selected===i?'chosen':''} onClick={()=>{setSelected(i);setMessage(`Index ${i} contains ${x}. Access is O(1).`)}} key={i}><b>{x}</b><small>{i}</small></button>)}</div><div className="controls"><input value={val} onChange={e=>setVal(e.target.value)} placeholder="Value" type="number"/><Button onClick={()=>{let n=Number(val);let index=arr.indexOf(n);setSelected(index);setMessage(index>-1?`${n} found at index ${index}. Search took up to O(n).`:`${n} is not in the array.`)}}>Search</Button><Button kind="ghost" onClick={()=>mutate(a=>[...a,Number(val||0)],`Inserted ${val||0} at the end.`)}>Insert</Button><Button kind="ghost" onClick={()=>selected!==null&&mutate(a=>a.filter((_,i)=>i!==selected),`Deleted index ${selected}.`)}>Delete</Button><button className="link-btn" onClick={()=>{setArr([10,25,7,42,18]);setMessage('Array reset.');setSelected(null)}}>Reset</button></div><p className="lab-message">{message}</p></div>}
function Quiz(){const [ans,setAns]=useState(null);let q=['O(1)','O(n)','O(log n)','O(n²)'];return <section className="quiz"><p className="eyebrow">KNOWLEDGE CHECK</p><h2>CHECK YOUR UNDERSTANDING</h2><p>What is the time complexity of accessing an array element by index?</p><div>{q.map((x,i)=><button key={x} className={ans===i?(i===0?'correct':'wrong'):''} onClick={()=>setAns(i)}>{x}</button>)}</div>{ans!==null&&<p className={ans===0?'success':'error'}>{ans===0?'Correct — an index calculates an element’s location directly.':'Not quite. Arrays give direct access by index, so it is O(1).'}</p>}</section>}
function TopicPage({id}){let t=topicInfo[id]||topicInfo.arrays;return <main className="topic-page"><a className="back" onClick={()=>go('/roadmap')}>← Back to roadmap</a><p className="eyebrow">LEARNING MODULE</p><h1>{t.title.toUpperCase()}</h1><p className="lead">{t.blurb}</p><div className="topic-stats"><div><span>DIFFICULTY</span><b>{t.difficulty}</b></div><div><span>ESTIMATED TIME</span><b>{t.time}</b></div><div><span>PROGRESS</span><b>{t.progress}%</b><Progress value={t.progress}/></div></div><section className="lesson-copy"><div><h2>What is it?</h2><p>{t.what}</p></div><div><h2>Why does it matter?</h2><p>{t.why}</p></div><div><h2>Real-world examples</h2><ul>{t.examples.map(x=><li key={x}>{x}</li>)}</ul></div></section>{id==='arrays'&&<section><h2>INTERACTIVE ARRAY</h2><p className="muted">Click a value to access it, then try an operation.</p><ArrayLab/></section>}<section><h2>COMPLEXITY AT A GLANCE</h2><table><thead><tr><th>Operation</th><th>Average</th><th>Worst</th></tr></thead><tbody>{[['Access','O(1)','O(1)'],['Search','O(n)','O(n)'],['Insert','O(n)','O(n)'],['Delete','O(n)','O(n)']].map(r=><tr key={r[0]}>{r.map(x=><td key={x} className="mono">{x}</td>)}</tr>)}</tbody></table></section><section><h2>CODE EXAMPLE</h2><CodeBlock/></section><Quiz/></main>}
function Practice(){const [difficulty,setDifficulty]=useState('All'),[status,setStatus]=useState('All'),[topic,setTopic]=useState('All');let list=problems.filter(p=>(difficulty==='All'||p.difficulty===difficulty)&&(status==='All'||(status==='Solved')===p.solved)&&(topic==='All'||p.topic===topic));return <main className="page"><p className="eyebrow">BUILD FLUENCY</p><h1>PRACTICE ARENA</h1><p className="lead">Turn concepts into problem-solving skills.</p><div className="filters selects">{[['Topic',topic,setTopic,['All','Arrays','Stack','Linked Lists','Trees','Graphs','Dynamic Programming']],['Difficulty',difficulty,setDifficulty,['All','Easy','Medium','Hard']],['Status',status,setStatus,['All','Solved','Unsolved']]].map(([l,v,set,opts])=><label key={l}>{l}<select value={v} onChange={e=>set(e.target.value)}>{opts.map(x=><option key={x}>{x}</option>)}</select></label>)}</div><div className="problem-grid">{list.map(p=><article className="problem" key={p.title}><div><span className={'pill '+p.difficulty.toLowerCase()}>{p.difficulty}</span>{p.solved&&<span className="solved">✓ Solved</span>}</div><h3>{p.title}</h3><p>{p.topic}</p><footer><span>⚡ +{p.xp} XP</span><small>{p.count} solved</small></footer><Button>Open problem</Button></article>)}</div></main>}
function StackLab({type='stack'}){const [values,setValues]=useState(type==='queue'?[10,20,30]:[10,20,30]),[input,setInput]=useState(''),[note,setNote]=useState('Ready.');let isQueue=type==='queue';let add=()=>{if(input){setValues(v=>[...v,Number(input)]);setNote(`${input} ${isQueue?'enqueued':'pushed'}.`);setInput('')}};let remove=()=>{let x=isQueue?values[0]:values.at(-1);setValues(v=>isQueue?v.slice(1):v.slice(0,-1));setNote(x===undefined?'Structure is empty.':`${x} ${isQueue?'dequeued':'popped'}.`)};return <div className="lab stack-lab"><div className={'stack-box '+(isQueue?'queue-box':'')}>{values.map((v,i)=><div key={i}>{v}</div>)}</div><p className="mono">{isQueue?'FRONT ← FIRST IN, FIRST OUT ← REAR':'TOP · LAST IN, FIRST OUT'}</p><div className="controls"><input type="number" value={input} onChange={e=>setInput(e.target.value)} placeholder="Enter value"/><Button onClick={add}>{isQueue?'Enqueue':'Push'}</Button><Button kind="ghost" onClick={remove}>{isQueue?'Dequeue':'Pop'}</Button><Button kind="ghost" onClick={()=>setNote(`${isQueue?'Front':'Top'}: ${isQueue?values[0]:values.at(-1)??'empty'}`)}>Peek</Button><button className="link-btn" onClick={()=>{setValues([10,20,30]);setNote('Reset.')}}>Reset</button></div><p className="lab-message">{note} {isQueue?'Enqueue, dequeue and peek are O(1).':'Push, pop and peek are O(1).'}</p></div>}
function SortLab(){const [a,setA]=useState([42,17,31,8,25]);const sort=()=>{let b=[...a],steps=[];for(let i=0;i<b.length;i++)for(let j=0;j<b.length-i-1;j++)if(b[j]>b[j+1]){[b[j],b[j+1]]=[b[j+1],b[j]];steps.push([...b])}steps.forEach((x,i)=>setTimeout(()=>setA(x),i*220))};return <div className="lab"><div className="bars">{a.map(x=><div key={x} style={{height:x*3}}><span>{x}</span></div>)}</div><Button onClick={sort}>Animate Bubble Sort</Button><button className="link-btn" onClick={()=>setA([42,17,31,8,25])}>Reset</button><p className="lab-message">Compare adjacent values and swap them when they are out of order. Worst case: O(n²).</p></div>}
function BinaryLab(){const arr=[4,9,13,18,23,31,37,44,52];const [target,setTarget]=useState(31),[visited,setVisited]=useState([]),[note,setNote]=useState('Choose a target, then start searching.');const run=()=>{let lo=0,hi=arr.length-1,steps=[];while(lo<=hi){let mid=Math.floor((lo+hi)/2);steps.push(mid);if(arr[mid]===target)break;if(arr[mid]<target)lo=mid+1;else hi=mid-1}steps.forEach((x,i)=>setTimeout(()=>{setVisited(s=>[...s,x]);if(arr[x]===target)setNote(`Found ${target} at index ${x} in ${i+1} steps.`)},i*500))};return <div className="lab"><div className="array-row binary-row">{arr.map((x,i)=><div key={x} className={visited.includes(i)?(x===target?'found':'checked'):''}>{x}</div>)}</div><div className="controls"><select value={target} onChange={e=>{setTarget(Number(e.target.value));setVisited([])}}>{arr.map(x=><option key={x}>{x}</option>)}</select><Button onClick={()=>{setVisited([]);setTimeout(run,50)}}>Start search</Button><button className="link-btn" onClick={()=>{setVisited([]);setNote('Search reset.')}}>Reset</button></div><p className="lab-message">{note} Binary search runs in O(log n) on sorted data.</p></div>}
function Visualizer(){const [active,setActive]=useState('Array');let labs={Array:<ArrayLab/>,Stack:<StackLab/>,Queue:<StackLab type="queue"/>, 'Binary Search':<BinaryLab/>, 'Bubble Sort':<SortLab/>, 'Linked List':<div className="lab linked"><div>10 <i>→</i> 25 <i>→</i> 42 <i>→</i> null</div><p className="lab-message">A linked list connects values through next references. Use the module lesson to explore nodes.</p></div>, 'Binary Tree':<GraphVisual/>};let names=Object.keys(labs);return <main className="page"><p className="eyebrow">HANDS-ON LEARNING</p><h1>INTERACTIVE DSA LAB</h1><p className="lead">See algorithms in action.</p><div className="visualizer-tabs">{names.map(n=><button className={n===active?'selected':''} onClick={()=>setActive(n)} key={n}>{n}</button>)}</div><section className="visualizer-stage"><div><span className="pill">INTERACTIVE</span><h2>{active.toUpperCase()} VISUALIZER</h2>{labs[active]}</div></section><h2>MORE LABS</h2><div className="coming-grid">{['Heap','BFS','DFS','Merge Sort'].map(x=><article key={x}><span>◌</span><h3>{x}</h3><p>Coming soon</p></article>)}</div></main>}
function Leaderboard(){const [period,setPeriod]=useState('All Time');return <main className="page"><p className="eyebrow">COMMUNITY RANKINGS</p><h1>ACM DSA LEADERBOARD</h1><p className="lead">Learn. Solve. Rise.</p><div className="filters">{['This Week','This Month','All Time'].map(x=><button className={x===period?'selected':''} onClick={()=>setPeriod(x)} key={x}>{x}</button>)}</div><section className="leaderboard"><div className="leader-head"><span>RANK</span><span>MEMBER</span><span>LEVEL</span><span>PROBLEMS</span><span>XP</span></div>{leaders.map((x,i)=><article className={i<3?'top':''} key={x.name}><b className="rank">{i+1}</b><div className="member"><i>{x.name.split(' ').map(n=>n[0]).join('')}</i><b>{x.name}</b>{x.name==='Prachi Jain'&&<small>You</small>}</div><span>Level {x.level}</span><span>{x.solved}</span><strong>{x.xp.toLocaleString()} XP</strong></article>)}</section></main>}
function ProgressPage(){let d=[['Arrays',80],['Strings',60],['Linked List',50],['Stack',70],['Trees',30],['Graphs',20],['Dynamic Programming',0]];return <main className="page"><p className="eyebrow">PRAchi JAIN / LEVEL 08</p><h1>YOUR DSA PROGRESS</h1><p className="lead">Keep building a consistent problem-solving practice.</p><section className="profile-card"><div className="big-avatar">PJ</div><div><h2>Prachi Jain</h2><p className="muted">Level 08 · 1,240 XP</p></div><div className="next-level"><span>NEXT LEVEL</span><b>1,500 XP</b><Progress value={83}/></div></section><div className="metric-grid">{[['38%','Overall'],['47','Problems'],['23','Lessons'],['7 days','Current Streak'],['1,240','XP'],['8','Level']].map(x=><div key={x[1]}><b>{x[0]}</b><span>{x[1]}</span></div>)}</div><section className="module-progress"><h2>MODULE PROGRESS</h2>{d.map(([n,v])=><div key={n}><span>{n}</span><Progress value={v}/><b>{v}%</b></div>)}</section><section className="badges"><h2>ACHIEVEMENTS</h2><div>{[['◈','FIRST STEP','Completed first lesson'],['▦','ARRAY EXPLORER','Completed Arrays module'],['↗','CODE RUNNER','Solved 25 problems'],['🔥','STREAK MASTER','7-day streak'],['♙','TREE CLIMBER','Complete Trees module'],['⌘','GRAPH NAVIGATOR','Complete Graphs module'],['★','DSA WARRIOR','Solve 100 problems']].map(x=><article key={x[1]}><i>{x[0]}</i><b>{x[1]}</b><small>{x[2]}</small></article>)}</div></section></main>}
function Search({onClose}){const [q,setQ]=useState('');let all=[...roadmap.map(x=>({name:x.title,path:'/learn/'+(topicInfo[x.id]?x.id:'arrays'),type:'Topic'})),...problems.map(x=>({name:x.title,path:'/practice',type:'Problem'})),{name:'Binary Search Visualizer',path:'/visualizer',type:'Visualizer'},{name:'Binary Tree',path:'/visualizer',type:'Visualizer'}];let found=all.filter(x=>x.name.toLowerCase().includes(q.toLowerCase())).slice(0,7);useEffect(()=>{setTimeout(()=>document.querySelector('.search-input')?.focus(),30)},[]);return <div className="overlay" onClick={onClose}><div className="search-modal" onClick={e=>e.stopPropagation()}><input className="search-input" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search topics, lessons, problems, visualizers…"/><p className="mono">{q?'RESULTS':'TRY “binary”, “array”, or “graph”'}</p>{q&&found.map(x=><button key={x.name} onClick={()=>{go(x.path);onClose()}}><span>{x.type}</span>{x.name}<b>→</b></button>)}{q&&!found.length&&<p className="muted">No matching learning resources found.</p>}</div></div>}
function App(){const [path,setPath]=useState(location.pathname),[search,setSearch]=useState(false);useEffect(()=>{const f=()=>setPath(location.pathname);addEventListener('popstate',f);const k=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearch(true)}};addEventListener('keydown',k);return()=>{removeEventListener('popstate',f);removeEventListener('keydown',k)}},[]);let page=path==='/'?<Home/>:path==='/roadmap'?<main className="page"><Timeline full/></main>:path==='/practice'?<Practice/>:path==='/visualizer'?<Visualizer/>:path==='/leaderboard'?<Leaderboard/>:path==='/progress'?<ProgressPage/>:path.startsWith('/learn/')?<TopicPage id={path.split('/').pop()}/>:<Home/>;return <><Navbar openSearch={()=>setSearch(true)}/>{page}<Footer/>{search&&<Search onClose={()=>setSearch(false)}/>}</>}
